$('#export-top-posts')?.addEventListener('click',()=>{if(!topPostsReport?.rows.length){toast('Load a report with posts first.');return;}const cell=value=>{let text=String(value??'');if(/^[=+\-@]/.test(text))text=`'${text}`;return /[",\n]/.test(text)?`"${text.replace(/"/g,'""')}"`:text;};const lines=[['Rank','Network','Published','Post','URL',...TOP_POST_COLUMNS.map(([,label])=>label)].map(cell).join(','),...topPostRows().map((row,index)=>[index+1,platformLabel(row.platform),row.publishedAt||'',row.text,row.url,...TOP_POST_COLUMNS.map(([key])=>row.metrics[key]??'')].map(cell).join(','))];const blob=new Blob([lines.join('\n')],{type:'text/csv'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`top-posts-${topPostsReport.clientName.replace(/[^a-z0-9]+/gi,'-').toLowerCase()}-${$('#top-posts-week').value}.csv`;link.click();URL.revokeObjectURL(url);toast('Top Posts exported.');});
