function renderTrendControls(){const focus=$('#trends-focus');if(!focus)return;const selected=focus.value||'all';focus.innerHTML=`<option value="all">All clients</option>${clients.map(client=>`<option value="${escapeHtml(client.id)}">${escapeHtml(client.name)}</option>`).join('')}<option value="custom">Custom niche…</option>`;focus.value=[...focus.options].some(option=>option.value===selected)?selected:'all';$('#trends-custom').hidden=focus.value!=='custom';$('#trend-platforms').innerHTML=Object.entries(TREND_PLATFORM_LABELS).map(([key,label])=>`<label class="day-chip"><input type="checkbox" value="${key}" ${trendPlatformsSelected.includes(key)?'checked':''}><span>${label}</span></label>`).join('');}
