function sourceLinks(urls){return(urls||[]).filter(url=>/^https:\/\//.test(url)).map(url=>{let host=url;try{host=new URL(url).hostname.replace(/^www\./,'');}catch{}return `<a href="${escapeHtml(url)}" target="_blank" rel="noopener">${escapeHtml(host)}</a>`;}).join(' · ');}
