function extractLinks(text){return[...new Set((String(text||'').match(/\b(?:https?:\/\/|www\.)[^\s<>"'`]+/gi)||[]).map(link=>link.replace(/[.,!?;:)\]]+$/,'')).map(link=>/^www\./i.test(link)?`https://${link}`:link))];}
function draftTexts(){const platforms=selectedPlatforms(),texts=[];if(!platforms.length||platforms.some(platform=>typeof platformOverrides[platform]?.text!=='string'))texts.push({key:'all',label:'Shared copy',text:$('#post-copy').value});platforms.filter(platform=>typeof platformOverrides[platform]?.text==='string').forEach(platform=>texts.push({key:`platform:${platform}`,label:`${platformLabel(platform)} copy`,text:platformOverrides[platform].text}));if(postOptions.firstComment.trim())texts.push({key:'firstComment',label:'First comment',text:postOptions.firstComment});postOptions.followUps.forEach((item,index)=>{if(item.comment.trim())texts.push({key:`followUp:${index}`,label:`Follow-up comment ${index+1}`,text:item.comment});});return texts.filter(item=>item.text.trim());}
