// Publishing queue: posts SignalDesk publishes itself, shown on the calendar, Command Center, and approvals.
const POST_STATUS_LABELS={pending_approval:'In Review',scheduled:'Scheduled',publishing:'Publishing',published:'Published',partial:'Partly published',failed:'Failed',canceled:'Canceled'};
const JOB_STATUS_LABELS={held:'Waiting for approval',queued:'Scheduled',publishing:'Publishing now',published:'Published',failed:'Failed',unknown:'Check the account',canceled:'Canceled'};
const CLIENT_STYLES={'coral-art':['event-coral','coral'],'gold-art':['event-gold','gold'],'green-art':['event-green','green-bg']};
const WORKER_GRACE_MS=5*60000;
let serverPostsLoading=false,serverPostsLoadedAt=0,openPostId=null,cancelArmed=false;
function clientStyle(client){const[cls,color]=CLIENT_STYLES[client?.color]||['event-purple','blue-bg'];return{cls,color};}
function serverCalendarPosts(){return serverPosts.filter(post=>post.status!=='canceled').map(post=>{const when=new Date(post.scheduledFor),client=clients.find(item=>item.id===post.clientId),style=clientStyle(client),name=client?.name||'Client';return{serverId:post.id,date:localIsoDate(when),day:when.toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'}).toUpperCase(),time:when.toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'}),at:when.getTime(),client:name,initials:client?.initials||name.split(' ').map(word=>word[0]).join('').slice(0,2),color:style.color,cls:style.cls,title:post.title||'Untitled post',channel:post.jobs.map(job=>platformLabel(job.platform)).join(', ')||'Social',status:POST_STATUS_LABELS[post.status]||post.status,autopilot:post.source==='autopilot',movable:currentRole==='admin'&&['pending_approval','scheduled'].includes(post.status)&&!post.jobs.some(job=>['publishing','published'].includes(job.status))};});}
function upcomingPosts(){if(!cloudFeaturesAvailable())return allPosts();const soon=Date.now()-3600000,server=serverCalendarPosts().filter(post=>post.at>=soon).sort((a,b)=>a.at-b.at);return[...server,...savedPosts.filter(post=>post.status==='Draft')];}
async function loadServerPosts(force=false){if(!cloudFeaturesAvailable()||serverPostsLoading)return;if(!force&&Date.now()-serverPostsLoadedAt<20000)return;serverPostsLoading=true;try{const from=addDays(startOfDay(new Date()),-35),data=await callSocialApi({action:'posts',from:from.toISOString(),to:addDays(from,100).toISOString()});serverPosts=data.posts||[];serverPostsLoadedAt=Date.now();renderUpcoming();renderCalendar();renderApprovals();refreshPostDialog();renderCommandCenter();}catch(error){console.error('Could not load scheduled posts:',error);}finally{serverPostsLoading=false;}}
function toLocalInput(date){const pad=value=>String(value).padStart(2,'0');return `${date.getFullYear()}-${pad(date.getMonth()+1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}`;}
function openPostDialog(id){const dialog=$('#post-dialog');if(!dialog)return;openPostId=id;cancelArmed=false;refreshPostDialog();if(!dialog.open)dialog.showModal();}
function jobRowHtml(post,job){const overdue=job.status==='queued'&&Date.parse(job.runAt)<Date.now()-WORKER_GRACE_MS,admin=currentRole==='admin';const detail=job.status==='unknown'?'The connection dropped after the post was sent, so it may already be live. Check the account before posting again.':job.error?job.error:overdue?'Past its time and still waiting. Make sure the publishing worker is scheduled (see the README).':job.status==='queued'&&job.attempts?`Retrying after a temporary problem (attempt ${job.attempts + 1}).`:'';const action=!admin?'':job.status==='failed'?`<button class="secondary-button" type="button" data-retry-job="${job.id}">Retry</button>`:job.status==='unknown'?`<button class="secondary-button" type="button" data-retry-job="${job.id}" data-confirmed="true">Not live — post again</button>`:'';return `<div class="job-row ${job.status}${overdue?' overdue':''}"><span class="platform-icon ${job.platform}">${escapeHtml(SOCIAL_NETWORKS.find(item=>item[0]===job.platform)?.[2]||'•')}</span><div><b>${escapeHtml(platformLabel(job.platform))}</b><small>${escapeHtml(JOB_STATUS_LABELS[job.status]||job.status)}${job.provider==='ayrshare'?' · via Ayrshare':''}${job.publishedAt?` · ${new Date(job.publishedAt).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}`:''}</small>${detail?`<p class="job-detail">${escapeHtml(detail)}</p>`:''}</div><div class="job-actions">${job.url?`<a class="secondary-link" href="${escapeHtml(job.url)}" target="_blank" rel="noopener">View ↗</a>`:''}${action}</div></div>`;}
function refreshPostDialog(){const dialog=$('#post-dialog'),body=$('#post-dialog-body');if(!dialog||!body||!openPostId)return;const post=serverPosts.find(item=>item.id===openPostId);if(!post){body.innerHTML=`<p class="option-hint">This post is no longer on the calendar.</p><div class="auth-actions"><button class="secondary-button" type="button" data-close-post>Close</button></div>`;return;}const client=clients.find(item=>item.id===post.clientId),when=new Date(post.scheduledFor),admin=currentRole==='admin',own=post.createdBy===activeUser?.id,pending=post.status==='pending_approval',movable=['pending_approval','scheduled'].includes(post.status)&&!post.jobs.some(job=>['publishing','published'].includes(job.status)),cancelable=(admin&&['pending_approval','scheduled','publishing','partial'].includes(post.status)&&post.jobs.some(job=>['held','queued'].includes(job.status)))||(own&&pending),media=post.media.slice(0,4).map(url=>/\.(mp4|mov|m4v|webm)(\?|$)/i.test(url)?`<span class="post-dialog-video">▶ Video</span>`:`<img src="${escapeHtml(url)}" alt="">`).join(''),custom=Object.keys(post.platformContent||{}).filter(platform=>post.platformContent[platform]?.text!==undefined);
body.innerHTML=`<div class="post-dialog-head"><div><small>${escapeHtml(client?.name||'Client')}${post.source==='autopilot'?' · ⚡ Autopilot':''}${post.parentId?' · Repost':''}</small><h2>${escapeHtml(post.title||'Untitled post')}</h2><p>${escapeHtml(when.toLocaleString('en-US',{weekday:'long',month:'long',day:'numeric',hour:'numeric',minute:'2-digit'}))}</p></div><span class="status ${statusClass(POST_STATUS_LABELS[post.status]||post.status)}">${escapeHtml(POST_STATUS_LABELS[post.status]||post.status)}</span></div>
<div class="post-dialog-copy">${escapeHtml(post.text)}</div>${custom.length?`<p class="option-hint">Custom copy for ${escapeHtml(custom.map(platformLabel).join(', '))}.</p>`:''}${media?`<div class="post-dialog-media">${media}</div>`:''}
<div class="job-list">${post.jobs.map(job=>jobRowHtml(post,job)).join('')}</div>${post.decisionNote?`<p class="option-hint">Approval note: ${escapeHtml(post.decisionNote)}</p>`:''}
${admin&&movable?`<div class="post-dialog-reschedule"><label class="field-label" for="post-dialog-time">Move to</label><div><input type="datetime-local" id="post-dialog-time" class="field" value="${toLocalInput(when)}"><button class="secondary-button" type="button" data-reschedule-post>Move</button></div></div>`:''}
<p class="auth-message" id="post-dialog-message" role="status"></p>
<div class="auth-actions">${postEditable(post)?`<button class="secondary-button" type="button" data-edit-post>Edit in Studio</button>`:''}${admin&&pending?`<button class="primary-button" type="button" data-approve-post>✓ Approve</button><button class="secondary-button" type="button" data-reject-post>Request changes</button>`:''}${cancelable?`<button class="secondary-button danger" type="button" data-cancel-post>${cancelArmed?'Click again to cancel':own&&pending&&!admin?'Withdraw post':'Cancel post'}</button>`:''}<button class="secondary-button" type="button" data-close-post>Close</button></div>`;}
async function postAction(payload,success){const message=$('#post-dialog-message');try{const result=await callSocialApi(payload);if(success)toast(typeof success==='function'?success(result):success);await loadServerPosts(true);return result;}catch(error){if(message)message.textContent=error.message;else toast(error.message);return null;}}
async function approveServerPost(id){const result=await postAction({action:'approve',postId:id},result=>result.late?'Approved. Its time had passed, so it publishes in the next minute.':'Approved and scheduled.');return result;}
async function rejectServerPost(id){const note=prompt('What should change? (Optional; the author sees this.)');if(note===null)return null;return postAction({action:'reject',postId:id,note},'Sent back to the author.');}
$('#post-dialog')?.addEventListener('click',async event=>{const dialog=$('#post-dialog');if(event.target===dialog||event.target.closest('[data-close-post]')){dialog.close();return;}const post=serverPosts.find(item=>item.id===openPostId);if(!post)return;if(event.target.closest('[data-edit-post]')){dialog.close();startEditingPost(post);return;}if(event.target.closest('[data-approve-post]')){await approveServerPost(post.id);return;}if(event.target.closest('[data-reject-post]')){if(await rejectServerPost(post.id))dialog.close();return;}if(event.target.closest('[data-cancel-post]')){if(!cancelArmed){cancelArmed=true;refreshPostDialog();return;}cancelArmed=false;if(await postAction({action:'cancel-post',postId:post.id},result=>result.keptPublished?'Canceled the rest. Networks it already reached keep the post.':'Post canceled.'))dialog.close();return;}if(event.target.closest('[data-reschedule-post]')){const value=$('#post-dialog-time').value,when=new Date(value);if(!value||isNaN(when)){$('#post-dialog-message').textContent='Choose a date and time.';return;}await postAction({action:'reschedule-post',postId:post.id,scheduleDate:when.toISOString()},`Moved to ${when.toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}.`);return;}const retry=event.target.closest('[data-retry-job]');if(retry){await postAction({action:'retry-job',jobId:retry.dataset.retryJob,confirmed:retry.dataset.confirmed==='true'},'Queued to publish again in the next minute.');}});
// The close event fires a moment later, so ignore it if another post was opened since.
$('#post-dialog')?.addEventListener('close',()=>{if(!$('#post-dialog').open){openPostId=null;cancelArmed=false;}});
document.addEventListener('click',event=>{const target=event.target.closest('[data-open-post]');if(!target||suppressOpenClick||event.target.closest('a,button:not([data-open-post])'))return;openPostDialog(target.dataset.openPost);});
document.addEventListener('keydown',event=>{if((event.key==='Enter'||event.key===' ')&&event.target.matches?.('[data-open-post][role=button]')){event.preventDefault();openPostDialog(event.target.dataset.openPost);}});
function serverApprovalRows(){return serverPosts.filter(post=>post.status==='pending_approval').map(post=>{const client=clients.find(item=>item.id===post.clientId),style=clientStyle(client),name=client?.name||'Client';return{serverId:post.id,title:post.title||'Untitled post',client:name,channel:post.jobs.map(job=>platformLabel(job.platform)).join(', '),by:post.source==='autopilot'?'Autopilot':post.createdBy===activeUser?.id?'You':'Teammate',status:'In Review',initials:post.source==='autopilot'?'AP':client?.initials||name.slice(0,2),color:style.color,scheduledFor:post.scheduledFor,autopilot:post.source==='autopilot'};});}
function renderApprovals(){const el=$('#approval-table');if(!el)return;const cloud=cloudFeaturesAvailable(),rows=cloud?serverApprovalRows():approvals,count=$('.nav-item[data-view="approvals"] .nav-count');if(count){const waiting=rows.filter(item=>item.status!=='Approved').length;count.textContent=waiting;count.hidden=!waiting;}if(!rows.length){el.innerHTML=`<p class="approval-empty">${cloud?'Nothing is waiting for approval.':'No sample approvals.'}</p>`;return;}el.innerHTML=rows.map((item,index)=>`<div class="approval-table-row" data-approval="${index}"><div class="approval-post"><div class="client-avatar ${item.color}">${escapeHtml(item.initials)}</div><div><b>${escapeHtml(item.title)}</b><small>${item.serverId?`${item.autopilot?'Autopilot · ':''}${new Date(item.scheduledFor).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}`:'Sample approval'}</small></div></div><div class="approval-client"><b>${escapeHtml(item.client)}</b><small>${escapeHtml(item.channel)}</small></div><div class="submitted-by">${escapeHtml(item.by)}</div><div><span class="status review">${escapeHtml(item.status)}</span></div><div class="approval-actions"><button class="approve" data-approve="${index}" ${item.status==='Approved'?'disabled':''}>✓ Approve</button>${item.serverId?`<button data-reject="${index}">Changes</button><button data-review="${index}">Review</button>`:`<button data-edit="${index}">Review</button>`}</div></div>`).join('');
$$('[data-approve]',el).forEach(button=>button.addEventListener('click',async()=>{const item=rows[+button.dataset.approve];if(item.serverId){button.disabled=true;await approveServerPost(item.serverId);button.disabled=false;return;}item.status='Approved';scheduleWorkspaceSave();toast(`“${item.title}” sample approval updated.`);renderApprovals();}));
$$('[data-reject]',el).forEach(button=>button.addEventListener('click',()=>rejectServerPost(rows[+button.dataset.reject].serverId)));
$$('[data-review]',el).forEach(button=>button.addEventListener('click',()=>openPostDialog(rows[+button.dataset.review].serverId)));
$$('[data-edit]',el).forEach(button=>button.addEventListener('click',()=>{const item=rows[+button.dataset.edit];showView('composer');$('#post-copy').value=`${item.title}\n\nAdd your caption here…`;selectVariant('all');scheduleDraftSave();toast('Draft opened in Publishing Studio');}));}

// Social account connections: direct sign-in with Meta, LinkedIn, and Pinterest; Ayrshare for other networks.
const DIRECT_PROVIDERS={facebook:'meta',instagram:'meta',linkedin:'linkedin',pinterest:'pinterest'};
const PROVIDER_NAMES={meta:'Facebook & Instagram',linkedin:'LinkedIn',pinterest:'Pinterest'};
let socialIntegrations=null,oauthSessionId=null,oauthPoll=null,oauthChecking=null;
function accountStateHtml(account,platform){const provider=DIRECT_PROVIDERS[platform],direct=account?.provider==='direct',days=account?.expiresAt?(Date.parse(account.expiresAt)-Date.now())/86400000:Infinity;if(direct&&account.status==='needs_reauth')return{state:'Reconnect needed',cls:'warning',detail:account.error||'The sign-in expired or was revoked.',buttons:`<button class="secondary-button" type="button" data-connect-provider="${provider}">Reconnect</button>`};if(direct&&account.linked)return{state:'Connected',cls:'connected',detail:`${account.displayName||account.username||'Connected'}${platform==='pinterest'&&account.boardId?` · Board: ${(account.boards||[]).find(board=>board.id===account.boardId)?.name||'chosen'}`:''}${platform==='linkedin'?account.kind==='organization'?' · Company Page':' · Personal profile':''}${days<14?` · Reconnect by ${new Date(account.expiresAt).toLocaleDateString('en-US',{month:'short',day:'numeric'})}`:''}`,buttons:`<button class="text-button" type="button" data-connect-provider="${provider}">Switch</button><button class="text-button" type="button" data-disconnect-platform="${platform}">Disconnect</button>`};if(account?.linked)return{state:'Connected',cls:'connected',detail:`${account.displayName||account.username||'Connected'} · via Ayrshare`,buttons:''};if(provider&&(account?.directAvailable||!socialIntegrations))return{state:'Not linked',cls:'disconnected',detail:'Not connected',buttons:account?.directAvailable?`<button class="primary-button" type="button" data-connect-provider="${provider}">Connect</button>`:''};if(account?.ayrshareAvailable)return{state:'Not linked',cls:'disconnected',detail:'Connect with “Connect via Ayrshare”',buttons:''};return{state:'Not set up',cls:'disconnected',detail:provider?`Add the ${PROVIDER_NAMES[provider]} app keys on the server to connect.`:'Needs Ayrshare on the server.',buttons:''};}
function renderSocialAccountCards(accounts=[]){const grid=$('#social-account-grid');if(!grid)return;const shown=SOCIAL_NETWORKS.filter(([platform])=>{const account=accounts.find(item=>item.platform===platform);return DIRECT_PROVIDERS[platform]||account?.linked||account?.ayrshareAvailable;});grid.innerHTML=shown.map(([platform,label,icon])=>{const account=accounts.find(item=>item.platform===platform),view=accountStateHtml(account,platform);return `<div class="social-account-card ${account?.linked?'is-connected':'is-unlinked'}"><span class="social-platform-icon ${platform}">${icon}</span><div class="social-account-copy"><b>${label}</b><small title="${escapeHtml(view.detail)}">${escapeHtml(view.detail)}</small>${view.buttons?`<div class="social-account-buttons">${view.buttons}</div>`:''}</div><span class="social-account-state ${view.cls}">${view.state}</span></div>`;}).join('');const ayrshare=$('#connect-social-accounts');if(ayrshare){ayrshare.hidden=!socialIntegrations?.ayrshare;ayrshare.textContent='＋ Connect via Ayrshare';}const note=$('.integration-note');if(note)note.textContent=socialIntegrations&&!socialIntegrations.ayrshare?'Facebook, Instagram, LinkedIn, and Pinterest connect directly. Other networks need Ayrshare, which isn’t set up on this server.':'Facebook, Instagram, LinkedIn, and Pinterest connect directly through each network. Other networks go through Ayrshare.';}
async function refreshSocialAccounts(){const client=selectedClient('#accounts-client-select');if(!client)return;const status=$('#social-accounts-status');if(!cloudFeaturesAvailable()){if(status)status.textContent='Sign in and configure Supabase to connect social accounts.';renderSocialAccountCards();return;}if(status)status.textContent='Checking linked accounts…';try{const data=await callSocialApi({action:'accounts',clientId:client.id});socialIntegrations=data.integrations||null;socialAccountCache.set(client.id,data.accounts||[]);renderSocialAccountCards(data.accounts||[]);const linked=(data.accounts||[]).filter(account=>account.linked).length,reauth=(data.accounts||[]).filter(account=>account.status==='needs_reauth').length;if(status)status.textContent=`${linked} connected network${linked===1?'':'s'} for ${client.name}.${reauth?` ${reauth} need${reauth===1?'s':''} reconnecting.`:''}${data.warning?` ${data.warning}`:''}`;}catch(error){renderSocialAccountCards(socialAccountCache.get(client.id)||[]);if(status)status.textContent=error.message;}}
async function startDirectConnect(provider){const client=selectedClient('#accounts-client-select');if(!client)return;const popup=window.open('about:blank','signaldesk-connect','width=620,height=760');if(!popup){toast('Allow pop-ups to connect accounts.');return;}try{const result=await callSocialApi({action:'oauth-start',clientId:client.id,provider}),target=new URL(result.url);if(!['www.facebook.com','www.linkedin.com','www.pinterest.com'].includes(target.hostname))throw new Error('The sign-in address looks wrong, so it was blocked.');oauthSessionId=result.sessionId;popup.location.href=target.href;clearInterval(oauthPoll);oauthPoll=setInterval(()=>{if(popup.closed){clearInterval(oauthPoll);if(oauthSessionId)checkOauthSession(oauthSessionId);}},800);}catch(error){popup.close();$('#social-accounts-status').textContent=error.message;toast(error.message);}}
window.addEventListener('message',event=>{if(event.origin!==location.origin||event.data?.type!=='signaldesk-oauth')return;if(event.data.sessionId&&event.data.sessionId===oauthSessionId)checkOauthSession(oauthSessionId);else if(!event.data.ok&&event.data.message)toast(event.data.message);});
async function checkOauthSession(id){if(oauthChecking===id)return;oauthChecking=id;try{const data=await callSocialApi({action:'oauth-session',sessionId:id});if(data.status==='authorized'){oauthSessionId=null;openConnectChooser(id,data);}else if(data.status==='failed'){oauthSessionId=null;toast(data.error||'The sign-in didn’t finish.');$('#social-accounts-status').textContent=data.error||'';}}catch(error){toast(error.message);}finally{oauthChecking=null;}}
function openConnectChooser(sessionId,data){const dialog=$('#connect-dialog');if(!dialog)return;const client=clients.find(item=>item.id===data.clientId),groups={};data.candidates.forEach(candidate=>(groups[candidate.platform]||=[]).push(candidate));dialog.dataset.session=sessionId;$('#connect-intro').textContent=`Pick the accounts to use for ${client?.name||'this client'}. You can connect one account per network.`;$('#connect-message').textContent='';$('#connect-options').innerHTML=Object.entries(groups).map(([platform,list])=>`<fieldset class="pref-group connect-group"><legend class="field-label">${escapeHtml(platformLabel(platform))}</legend>${list.map((candidate,index)=>`<label class="option-toggle connect-choice"><input type="radio" name="pick-${platform}" value="${escapeHtml(candidate.key)}" ${index===0?'checked':''}><span><b>${escapeHtml(candidate.displayName||candidate.username||candidate.externalId)}</b>${candidate.note?`<small>${escapeHtml(candidate.note)}</small>`:''}</span></label>${platform==='pinterest'&&candidate.boards?.length?`<select class="field" data-board-for="${escapeHtml(candidate.key)}" aria-label="Board for new Pins">${candidate.boards.map(board=>`<option value="${escapeHtml(board.id)}">${escapeHtml(board.name)}</option>`).join('')}</select>`:''}`).join('')}<label class="option-toggle connect-choice"><input type="radio" name="pick-${platform}" value=""><span>Don’t connect ${escapeHtml(platformLabel(platform))}</span></label></fieldset>`).join('');dialog.showModal();}
$('#connect-form')?.addEventListener('submit',async event=>{event.preventDefault();const dialog=$('#connect-dialog'),selections=$$('#connect-options input[type=radio]:checked').filter(input=>input.value).map(input=>{const board=$(`[data-board-for="${CSS.escape(input.value)}"]`);return board?{key:input.value,boardId:board.value}:{key:input.value};});if(!selections.length){$('#connect-message').textContent='Choose at least one account.';return;}try{const result=await callSocialApi({action:'oauth-finish',sessionId:dialog.dataset.session,selections});dialog.close();toast(`Connected ${result.connected.map(platformLabel).join(', ')}.`);refreshSocialAccounts();}catch(error){$('#connect-message').textContent=error.message;}});
$('#connect-cancel')?.addEventListener('click',()=>$('#connect-dialog').close());
$('#social-account-grid')?.addEventListener('click',async event=>{const connect=event.target.closest('[data-connect-provider]');if(connect){startDirectConnect(connect.dataset.connectProvider);return;}const disconnect=event.target.closest('[data-disconnect-platform]');if(!disconnect)return;const client=selectedClient('#accounts-client-select'),platform=disconnect.dataset.disconnectPlatform;if(disconnect.dataset.armed!=='true'){disconnect.dataset.armed='true';disconnect.textContent='Click to confirm';setTimeout(()=>{if(disconnect.isConnected){disconnect.dataset.armed='';disconnect.textContent='Disconnect';}},4000);return;}try{const result=await callSocialApi({action:'disconnect',clientId:client.id,platform});toast(result.waitingPosts?`${platformLabel(platform)} disconnected. ${result.waitingPosts} scheduled post${result.waitingPosts===1?'':'s'} to it will fail until you reconnect.`:`${platformLabel(platform)} disconnected.`);refreshSocialAccounts();}catch(error){toast(error.message);}});

// Pinterest options in the composer.
