// Command Center: real numbers when signed in. Demo mode keeps the sample dashboard.
let overviewSummary=null,overviewLoading=false;
const compactNumber=value=>new Intl.NumberFormat('en-US',{notation:'compact',maximumFractionDigits:1}).format(value||0);
const shortWhen=iso=>new Date(iso).toLocaleString('en-US',{weekday:'short',hour:'numeric',minute:'2-digit'});
async function loadOverview(){if(!cloudFeaturesAvailable()||overviewLoading)return;overviewLoading=true;try{overviewSummary=await callSocialApi({action:'overview'});renderCommandCenter();}catch(error){console.error('Could not load the Command Center:',error);}finally{overviewLoading=false;}}
function attentionItems(){const items=[],now=Date.now(),admin=currentRole==='admin',clientName=id=>clients.find(item=>item.id===id)?.name||'Client',networks=jobs=>jobs.map(job=>platformLabel(job.platform)).join(', ');const upcoming=serverPosts.filter(post=>['scheduled','pending_approval'].includes(post.status)&&Date.parse(post.scheduledFor)<now+7*86400000);
if(admin&&overviewSummary?.worker?.stale&&(upcoming.length||serverPosts.some(post=>post.jobs.some(job=>job.status==='queued'&&Date.parse(job.runAt)<now))))items.push({kind:'worker',title:'Scheduled posts aren’t going out',detail:overviewSummary.worker.lastRun?`The publishing worker last ran ${timeAgo(overviewSummary.worker.lastRun)}.`:'The publishing worker hasn’t run yet.',meta:'Check the scheduler (README, Publishing setup step 3)',tone:'danger'});
serverPosts.filter(post=>post.jobs.some(job=>['failed','unknown'].includes(job.status))).forEach(post=>{const bad=post.jobs.filter(job=>['failed','unknown'].includes(job.status));items.push({kind:'post',id:post.id,title:post.title||'Untitled post',detail:`${clientName(post.clientId)} · ${bad.some(job=>job.status==='unknown')?'Check':'Failed on'} ${networks(bad)}`,meta:bad[0].error||'Open to retry',tone:'danger'});});
(admin?overviewSummary?.connections?.reauth||[]:[]).forEach(item=>items.push({kind:'view',view:'social-accounts',title:`Reconnect ${platformLabel(item.platform)}`,detail:clientName(item.clientId),meta:'Scheduled posts to it will fail until then',tone:'warning'}));
serverPosts.filter(post=>post.status==='pending_approval').forEach(post=>items.push({kind:'post',id:post.id,title:post.title||'Untitled post',detail:`${clientName(post.clientId)} · ${networks(post.jobs)}`,meta:`Waiting for approval · goes out ${shortWhen(post.scheduledFor)}`,tone:'pending'}));
return items;}
function sparkPath(values,width,height){const max=Math.max(...values,1),step=width/Math.max(values.length-1,1);return values.map((value,index)=>`${index?'L':'M'}${Math.round(index*step*10)/10} ${Math.round((height-3-(value/max)*(height-6))*10)/10}`).join(' ');}
function renderCommandCenter(){if(!cloudFeaturesAvailable())return;const grid=$('.stats-grid');if(!grid)return;const now=Date.now(),today=startOfDay(new Date()),days=Array.from({length:7},(_,index)=>addDays(today,index)),live=serverPosts.filter(post=>['scheduled','pending_approval','publishing'].includes(post.status)),upcoming=live.filter(post=>{const at=Date.parse(post.scheduledFor);return at>=now-3600000&&at<addDays(today,7).getTime();}),perDay=days.map(day=>upcoming.filter(post=>localIsoDate(new Date(post.scheduledFor))===localIsoDate(day)).length),maxDay=Math.max(...perDay,1),pending=serverPosts.filter(post=>post.status==='pending_approval').length,engagement=overviewSummary?.engagement,connections=overviewSummary?.connections,change=engagement&&engagement.previous?Math.round((engagement.total-engagement.previous)/engagement.previous*1000)/10:null,icons=Object.fromEntries(SOCIAL_NETWORKS.map(([key,,icon])=>[key,icon]));
grid.innerHTML=`<div class="stat-card"><div class="stat-top"><span>Scheduled next 7 days</span><span class="stat-symbol purple">▦</span></div><div class="stat-number">${upcoming.length}</div><div class="stat-foot">${perDay[0]?`<span class="trend neutral">${perDay[0]} today</span>`:'<span class="trend neutral">Nothing today</span>'}</div><div class="mini-bars" title="Posts per day, starting today">${perDay.map(count=>`<i style="height:${Math.max(6,Math.round(count/maxDay*100))}%"></i>`).join('')}</div></div>
<div class="stat-card"><div class="stat-top"><span>Awaiting approval</span><span class="stat-symbol amber">◷</span></div><div class="stat-number">${pending}</div><div class="stat-foot"><span class="trend neutral">${pending?'Needs a decision':'All clear'}</span></div><div class="stat-progress"><span style="width:${live.length?Math.round(pending/live.length*100):0}%"></span></div></div>
<div class="stat-card"><div class="stat-top"><span>Engagement, last 30 days</span><span class="stat-symbol green">♡</span></div><div class="stat-number">${engagement?compactNumber(engagement.total):'—'}</div><div class="stat-foot">${!engagement?'Loading…':!engagement.measured?'Appears once published posts report metrics':change===null?`From ${engagement.measured} post${engagement.measured===1?'':'s'}`:`<span class="trend ${change>=0?'up':'down'}">${change>=0?'↗':'↘'} ${Math.abs(change)}%</span> vs. previous 30 days`}</div>${engagement?.measured?`<div class="sparkline"><svg viewBox="0 0 160 40" preserveAspectRatio="none"><path d="${sparkPath(engagement.daily.map(day=>day.engagements),160,40)}" fill="none" stroke="currentColor" stroke-width="2.5"/></svg></div>`:''}</div>
<div class="stat-card"><div class="stat-top"><span>Connected accounts</span><span class="stat-symbol blue">◎</span></div><div class="stat-number">${connections?connections.active:'—'}${connections&&connections.reauth.length?`<span class="stat-denom">/ ${connections.active+connections.reauth.length}</span>`:''}</div><div class="stat-foot">${!connections?'Loading…':connections.reauth.length?`<span class="trend down">${connections.reauth.length} need${connections.reauth.length===1?'s':''} reconnecting</span>`:connections.active?`Across ${connections.clients} client${connections.clients===1?'':'s'}`:'Connect accounts in Social Accounts'}</div><div class="account-dots">${(connections?.platforms||[]).map(platform=>`<i title="${escapeHtml(platformLabel(platform))}">${icons[platform]||'•'}</i>`).join('')}</div></div>`;
const items=attentionItems(),panel=$('.approval-panel');if(panel){$('.panel-header p',panel).textContent='Approvals, failed posts, and accounts to reconnect.';$('.count-badge',panel).textContent=items.length;$('.approval-list',panel).innerHTML=items.length?items.slice(0,5).map(item=>`<div class="approval-item attention-${item.tone}" role="button" tabindex="0" ${item.kind==='post'?`data-open-post="${item.id}"`:item.kind==='view'?`data-view="${item.view}"`:''}><span class="attention-dot"></span><div class="approval-copy"><b>${escapeHtml(item.title)}</b><span>${escapeHtml(item.detail)}</span><small>${escapeHtml(item.meta)}</small></div></div>`).join('')+(items.length>5?`<p class="option-hint">And ${items.length-5} more.</p>`:''):'<p class="attention-empty">Nothing needs you right now.</p>';}
const navCount=$('.nav-item[data-view="overview"] .nav-count');if(navCount){navCount.textContent=items.length;navCount.hidden=!items.length;}const inboxCount=$('.nav-item[data-view="inbox"] .nav-count');if(inboxCount)inboxCount.hidden=true;
renderPerformance();}
function renderPerformance(){const panel=$('.performance-panel');if(!panel||!overviewSummary)return;const engagement=overviewSummary.engagement,chip=$('.panel-header .filter-chip',panel);if(chip)chip.outerHTML='<span class="performance-range">Last 30 days</span>';$('.panel-header p',panel).textContent='Engagement on posts published through SignalDesk.';const body=$('.performance-content',panel);if(!engagement.measured){body.innerHTML='<p class="attention-empty">Engagement shows up here once published posts report metrics. SignalDesk checks recent posts every few hours.</p>';return;}const values=engagement.daily.map(day=>day.engagements),max=Math.max(...values,1),top=Math.ceil(max/4)*4||4,width=600,height=170,step=width/(values.length-1),points=values.map((value,index)=>[Math.round(index*step),Math.round(height-(value/top)*(height-10))]),line=points.map(([x,y],index)=>`${index?'L':'M'}${x} ${y}`).join(' '),labels=[0,5,10,15,20,25,29].map(index=>new Date(`${engagement.daily[index].day}T12:00:00`).toLocaleDateString('en-US',{month:'short',day:'numeric'})),platforms=Object.entries(engagement.byPlatform).sort((a,b)=>b[1]-a[1]).slice(0,5),best=platforms[0]?.[1]||1;
body.innerHTML=`<div class="chart-wrap"><div class="chart-y">${[top,top*.75,top*.5,top*.25,0].map(value=>`<span>${compactNumber(value)}</span>`).join('')}</div><div class="chart"><div class="chart-grid"><i></i><i></i><i></i><i></i><i></i></div><svg viewBox="0 0 ${width} ${height}" preserveAspectRatio="none" role="img" aria-label="Daily engagement over the last 30 days"><path d="${line} L${width} ${height} L0 ${height}Z" fill="#5b8db8" fill-opacity=".12"/><path d="${line}" fill="none" stroke="#5b8db8" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></svg><div class="chart-x">${labels.map(label=>`<span>${label}</span>`).join('')}</div></div></div><div class="channel-rank"><div class="rank-title">By channel <span>Engagements</span></div>${platforms.map(([platform,value])=>`<div class="rank-row"><span class="platform-icon ${platform}">${escapeHtml(SOCIAL_NETWORKS.find(item=>item[0]===platform)?.[2]||'•')}</span><div class="rank-copy"><b>${escapeHtml(platformLabel(platform))}</b><div class="rank-bar"><i style="width:${Math.max(4,Math.round(value/best*100))}%"></i></div></div><strong>${value.toLocaleString('en-US')}</strong></div>`).join('')}</div>`;}
document.addEventListener('keydown',event=>{if((event.key==='Enter'||event.key===' ')&&event.target.matches?.('.approval-item[data-view][role=button]')){event.preventDefault();showView(event.target.dataset.view);}});

// Upcoming content filters on the Command Center.
function upcomingFilter(post){const client=$('#upcoming-client')?.value||'',channel=$('#upcoming-channel')?.value||'';return(!client||post.client===client)&&(!channel||String(post.channel||'').split(/,\s*/).includes(channel));}
function renderUpcomingFilters(){const row=$('#view-overview .filter-row');if(!row)return;if(!$('#upcoming-client')){row.innerHTML='<select id="upcoming-client" class="field calendar-filter" aria-label="Filter upcoming posts by client"></select><select id="upcoming-channel" class="field calendar-filter" aria-label="Filter upcoming posts by network"></select>';$('#upcoming-client').addEventListener('change',renderUpcoming);$('#upcoming-channel').addEventListener('change',renderUpcoming);}const clientSelect=$('#upcoming-client'),channelSelect=$('#upcoming-channel'),client=clientSelect.value,channel=channelSelect.value,channels=[...new Set(upcomingPosts().flatMap(post=>String(post.channel||'').split(/,\s*/)).filter(Boolean))].sort();clientSelect.innerHTML='<option value="">All clients</option>'+clients.map(item=>`<option value="${escapeHtml(item.name)}">${escapeHtml(item.name)}</option>`).join('');clientSelect.value=clients.some(item=>item.name===client)?client:'';channelSelect.innerHTML='<option value="">All networks</option>'+channels.map(item=>`<option value="${escapeHtml(item)}">${escapeHtml(item)}</option>`).join('');channelSelect.value=channels.includes(channel)?channel:'';}

// Drag a scheduled post to a new day or time on the Day and Week timelines.
const DRAG_SNAP_MINUTES=15;
let calendarDrag=null,suppressOpenClick=false;
document.addEventListener('pointerdown',event=>{const el=event.target.closest('.timeline-event[data-draggable]');if(!el||event.button!==0)return;calendarDrag={el,id:el.dataset.openPost,x:event.clientX,y:event.clientY,grab:event.clientY-el.getBoundingClientRect().top,origin:el.parentElement,moved:false,pointerId:event.pointerId};});
document.addEventListener('pointermove',event=>{const drag=calendarDrag;if(!drag)return;if(!drag.moved){if(Math.hypot(event.clientX-drag.x,event.clientY-drag.y)<6)return;drag.moved=true;drag.el.classList.add('dragging');try{drag.el.setPointerCapture(drag.pointerId);}catch{}}event.preventDefault();const scroll=$('#timeline-scroll');if(scroll){const box=scroll.getBoundingClientRect();if(event.clientY<box.top+28)scroll.scrollTop-=12;else if(event.clientY>box.bottom-28)scroll.scrollTop+=12;}drag.el.style.pointerEvents='none';const col=document.elementFromPoint(event.clientX,event.clientY)?.closest('.timeline-col')||drag.target||drag.origin;drag.el.style.pointerEvents='';if(col!==drag.el.parentElement)col.appendChild(drag.el);drag.target=col;const top=event.clientY-col.getBoundingClientRect().top-drag.grab,minutes=Math.min(24*60-DRAG_SNAP_MINUTES,Math.max(0,Math.round(top/HOUR_HEIGHT*60/DRAG_SNAP_MINUTES)*DRAG_SNAP_MINUTES));drag.minutes=minutes;Object.assign(drag.el.style,{top:`${minutes/60*HOUR_HEIGHT+1}px`,left:'3px',width:'calc(100% - 6px)'});const label=$('b',drag.el);if(label)label.textContent=new Date(2000,0,1,Math.floor(minutes/60),minutes%60).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'});});
document.addEventListener('pointerup',async()=>{const drag=calendarDrag;calendarDrag=null;if(!drag?.moved)return;suppressOpenClick=true;setTimeout(()=>{suppressOpenClick=false;},0);const[year,month,day]=drag.target.dataset.date.split('-').map(Number),when=new Date(year,month-1,day,Math.floor(drag.minutes/60),drag.minutes%60),post=serverPosts.find(item=>item.id===drag.id);if(!post){renderCalendar();return;}if(Math.abs(when-new Date(post.scheduledFor))<60000){renderCalendar();return;}if(when.getTime()<=Date.now()+60000){toast('Choose a time in the future.');renderCalendar();return;}const previous=post.scheduledFor;post.scheduledFor=when.toISOString();post.jobs.forEach(job=>{if(['held','queued'].includes(job.status))job.runAt=post.scheduledFor;});renderCalendar();try{await callSocialApi({action:'reschedule-post',postId:post.id,scheduleDate:post.scheduledFor});toast(`Moved “${post.title||'post'}” to ${when.toLocaleString('en-US',{weekday:'short',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}.`);}catch(error){post.scheduledFor=previous;renderCalendar();toast(error.message);}loadServerPosts(true);});
document.addEventListener('pointercancel',()=>{if(calendarDrag?.moved)renderCalendar();calendarDrag=null;});

// Editing a scheduled post in the Publishing Studio. The person's own draft is set aside and restored afterwards.
let editingPost=null,stashedDraft=null;
function mediaFromUrl(url){return{path:url.split('/object/public/social-media/')[1]||'',url,name:decodeURIComponent(url.split('/').pop().split('?')[0]),type:/\.(mp4|mov|m4v|webm)(\?|$)/i.test(url)?'video/mp4':'image/jpeg'};}
function optionsToComposer(options={}){const visibility={};['linkedin','youtube','tiktok'].forEach(platform=>{if(options[platform]?.visibility)visibility[platform]=options[platform].visibility;});return normalizePostOptions({collaborators:(options.instagramOptions?.collaborators||[]).join(', '),tags:(options.instagramOptions?.userTags||[]).map(tag=>tag.username).join(', '),visibility,firstComment:options.firstComment?.comment||'',followUps:(options.followUpComments||[]).map(item=>({comment:item.comment,delayMinutes:item.delayMinutes})),repost:options.reposts?{enabled:true,repeat:options.reposts.repeat,days:options.reposts.days}:{enabled:false},pinterest:options.pinterest||{}});}
function postEditable(post){const admin=currentRole==='admin',own=post.createdBy===activeUser?.id,pending=post.status==='pending_approval',untouched=['pending_approval','scheduled'].includes(post.status)&&!post.jobs.some(job=>['publishing','published'].includes(job.status));if(post.parentId||!untouched)return false;if(admin)return pending||Date.parse(post.scheduledFor)>Date.now()+120000;return own&&pending;}
function startEditingPost(post){if(!editingPost)stashedDraft=collectDraftStateRaw();editingPost={id:post.id,title:post.title||'Untitled post',platforms:post.jobs.filter(job=>job.status!=='canceled').map(job=>job.platform),scheduledFor:post.scheduledFor};applyDraftState({draft:post.text,uploadedMedia:post.media.map(mediaFromUrl),draftOverrides:Object.fromEntries(Object.entries(post.platformContent||{}).map(([platform,content])=>[platform,{...(typeof content.text==='string'?{text:content.text}:{}),...(Array.isArray(content.media)?{media:content.media.map(mediaFromUrl)}:{})}])),postOptions:optionsToComposer(post.options)});const client=clients.find(item=>item.id===post.clientId);if(client)$('#client-select').value=client.name;const when=new Date(post.scheduledFor);$('#schedule-date').value=localIsoDate(when);$('#schedule-time').value=`${String(when.getHours()).padStart(2,'0')}:${String(when.getMinutes()).padStart(2,'0')}`;selectVariant('all');showView('composer');renderEditingState();}
function applyEditingPlatforms(){if(!editingPost)return;$$('.account-select input[type=checkbox]').forEach(input=>{input.checked=editingPost.platforms.includes(input.value);});}
function renderEditingState(){const banner=$('#editing-banner'),editing=Boolean(editingPost),admin=currentRole==='admin';if(banner){banner.hidden=!editing;if(editing)$('#editing-text').textContent=`Editing “${editingPost.title}”, scheduled for ${new Date(editingPost.scheduledFor).toLocaleString('en-US',{weekday:'short',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}.`;}['#save-draft','#clear-draft'].forEach(selector=>{const el=$(selector);if(el)el.hidden=editing;});$('#schedule-post').textContent=editing?'Save changes':'Schedule post';$('#submit-review').textContent=editing?(admin?'Save and send for approval':'Save and resubmit'):(admin?'Send for approval':'Submit for approval');}
function stopEditing(){if(!editingPost)return;editingPost=null;if(stashedDraft)applyDraftState(stashedDraft);stashedDraft=null;renderEditingState();updatePreview();}
$('#cancel-edit')?.addEventListener('click',()=>{stopEditing();toast('Editing canceled. The scheduled post is unchanged.');});
$('#personal-mode')?.addEventListener('change',()=>{applyPersonalMode();scheduleWorkspaceSave();});
setInterval(()=>{if(document.visibilityState==='visible'&&['view-calendar','view-overview','view-approvals'].includes($('.page.active')?.id))loadServerPosts();},60000);
loadWorkspaceState().catch(error=>{console.error('Workspace load failed:',error);setStorageStatus('Connection failed');toast('Could not load workspace data. Check your Supabase setup.');renderWorkspace();});
